    /**
     * The type for the zone.
     *
     * Possible values are `DEFAULT_ZONE` and `REGULAR_CUSTOM_ZONE`.
     */
    zoneType: string;
    /**
     * A Boolean value that indicates whether the zone is a default zone.
     */
